// Build Alert
// Turns the Error Trigger payload into a Slack message, an email and an audit log record.
// Handles both shapes n8n sends: a failed execution, or a trigger that failed to start.

const cfg = $('Config').first().json.config;
const e = $input.first().json;
const exec = e.execution || {};
const trig = e.trigger || {};
const err = exec.error || trig.error || {};

const workflowName = e.workflow?.name || 'Unknown workflow';
const failedNode = exec.lastNodeExecuted || err.node?.name || (e.trigger ? 'Trigger' : 'Unknown step');
const message = String(err.message || 'No error message was provided');
const description = String(err.description || '');
const executionId = exec.id ? String(exec.id) : '';
const url = exec.url || '';
const when = new Date().toLocaleString('en-US', { timeZone: cfg.timezone || 'America/New_York' });

const slackText = [
  `:rotating_light: *Workflow failed: ${workflowName}*`,
  `*Step:* ${failedNode}`,
  `*Error:* ${message}`,
  description ? `*Details:* ${description.slice(0, 500)}` : null,
  `*Execution:* ${url ? `<${url}|Open execution ${executionId}>` : executionId || 'n/a'}${exec.retryOf ? ` (retry of ${exec.retryOf})` : ''}`,
  `*When:* ${when}`,
  '_Fix the cause, open the execution and click Retry. Writes are idempotent, so a retry cannot create duplicates._',
].filter(Boolean).join('\n');

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const emailHtml = `
<p><strong>${esc(workflowName)}</strong> failed at step <strong>${esc(failedNode)}</strong>.</p>
<p><strong>Error:</strong> ${esc(message)}</p>
${description ? `<p><strong>Details:</strong> ${esc(description.slice(0, 1000))}</p>` : ''}
<p><strong>When:</strong> ${esc(when)}</p>
${url ? `<p><a href="${url}">Open execution ${esc(executionId)}</a></p>` : ''}
<p>Fix the cause, open the execution and click Retry. Writes are idempotent, so a retry cannot create duplicates.</p>`;

return [{
  json: {
    slack_text: slackText,
    email_subject: `[Lead Router] ${workflowName} failed at "${failedNode}"`,
    email_html: emailHtml,
    log_record: {
      event: 'error',
      reason: message.slice(0, 1000),
      details: {
        workflow_id: e.workflow?.id || null,
        workflow_name: workflowName,
        failed_node: failedNode,
        description,
        execution_id: executionId || null,
        execution_url: url || null,
        retry_of: exec.retryOf || null,
        mode: exec.mode || trig.mode || null,
      },
      workflow_name: workflowName,
      execution_id: executionId || null,
    },
  },
}];
